<?php require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/auth.php';require_admin();$summary=$mysqli->query("SELECT COUNT(*) bookings,COALESCE(SUM(parking_amount),0) parking,COALESCE(SUM(fine_amount),0) fines FROM bookings WHERE DATE(created_at)=CURDATE()")->fetch_assoc();$rows=$mysqli->query("SELECT DATE(created_at) day,COUNT(*) bookings,COALESCE(SUM(parking_amount+fine_amount),0) revenue FROM bookings GROUP BY DATE(created_at) ORDER BY day DESC LIMIT 30");$page_title='Reports';require __DIR__.'/../includes/header.php'; ?>
<h2>Reports</h2><div class="row g-3 my-2"><div class="col-md-4"><div class="card p-3 shadow-sm border-0"><small class="text-muted">Today's bookings</small><strong class="h3"><?=$summary['bookings']?></strong></div></div><div class="col-md-4"><div class="card p-3 shadow-sm border-0"><small class="text-muted">Today's parking revenue</small><strong class="h3">₹<?=number_format($summary['parking'],2)?></strong></div></div><div class="col-md-4"><div class="card p-3 shadow-sm border-0"><small class="text-muted">Today's fines</small><strong class="h3">₹<?=number_format($summary['fines'],2)?></strong></div></div></div><div class="card shadow-sm border-0 mt-3"><div class="card-header bg-white"><b>Daily activity</b></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Date</th><th>Bookings</th><th>Revenue</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['day'])?></td><td><?=$r['bookings']?></td><td>₹<?=number_format($r['revenue'],2)?></td></tr><?php endwhile;?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
